set_time_limit(120);
$base = __DIR__;

function fmWrite($base, $rel, $gz_b64) {
    $dir = dirname("$base/$rel");
    if (!is_dir($dir)) mkdir($dir, 0755, true);
    return file_put_contents("$base/$rel", gzdecode(base64_decode($gz_b64))) !== false;
}

$ok = []; $errors = [];
$files = [
    'admin/analytics.php' => '',
    'admin/index.php' => '',
    'admin/payouts.php' => '',
    'admin/settings.php' => '',
    'admin/transactions.php' => '',
    'assets/js/main.js' => '',
    'login.html' => '',
    'products/demat.html' => '',
    'products/insurance.html' => '',
    'products/investments.html' => '',
    'products/personal-loan.html' => '',
];
foreach ($files as $r => $b) { if(fmWrite($base,$r,$b)) $ok[]=$r; else $errors[]=$r; }
include_once 'deploy3.php';
?>
